mapper.select:
select t.heartbeat_time,t.heartbeat_time heartbeatTime,t.success_prompt,t.success_prompt
successPrompt,t.impl_bean,t.impl_bean implBean,t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code
machineCode,t.machine_port,t.machine_port machinePort,t.fail_prompt,t.fail_prompt
failPrompt,t.status_cd,t.status_cd statusCd,t.community_id,t.community_id
communityId,t.machine_name,t.machine_name machineName,t.machine_ip,t.machine_ip machineIp,t.create_time createTime
from tel_machine t
where 1 =1

    and t.heartbeat_time= #{heartbeatTime}


    and t.success_prompt= #{successPrompt}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.machine_port= #{machinePort}


    and t.fail_prompt= #{failPrompt}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}

order by t.create_time desc

    limit #{page}, #{row}

